{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "A charter school authorized by the state charter commission and the local board of education of the school district where it is located could agree in writing, within 30 calendar days of the school's authorization, that the local board will become the authorizer and the school district for that school. The local board would then take on the rights and responsibilities of the charter agreement. The agreement would have to be filed with the commission in the way the commission sets. This option would not apply to a charter school whose charter agreement the commission renewed on appeal.",
      "rationale": "Conveys the eligible parties, written agreement, 30-calendar-day deadline, local board's new roles and responsibilities, and exception for renewals on appeal. Omission of the routine notwithstanding cross-reference does not materially reduce coverage."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The agreement would have to be filed with the commission in the way the commission sets.",
      "rationale": "States both the filing requirement and the commission's authority to prescribe the manner of filing."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Second, it would change Section 49-13-110(b)(1) so that it applies to an \"initial\" charter agreement rather than \"a\" charter agreement.",
      "rationale": "Identifies the amended provision and conveys the replacement limiting its wording to an initial charter agreement."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Third, it would set renewal terms in both Section 49-13-110(c) and Section 49-13-121(g). If a local board of education approves a renewal application, the renewed charter agreement must last ten academic years.",
      "rationale": "Identifies both amended provisions and the mandatory ten-academic-year term for local-board-approved renewals."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "If the commission approves a renewal application, the term must be at least five and no more than ten academic years, set by commission resolution.",
      "rationale": "Conveys commission approval as the condition, both term limits, and determination by commission resolution."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Fourth, it would remove opening words from Sections 49-13-121(f)(3) and 49-13-121(l). Those words made the provisions apply notwithstanding subsection (g), the first sentence of 49-13-110(b), and 49-13-110(c). Each provision would now begin simply with \"If.\"",
      "rationale": "Identifies both amendment targets, the removed notwithstanding language, and the replacement opening."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The act would take effect when it becomes law.",
      "rationale": "Accurately conveys the effective-date provision."
    }
  ]
}
